    for c in range(c0, c1 + 1):
        if out[r0][c] == bg:
            out[r0][c] = 2
        if out[r1][c] == bg:
            out[r1][c] = 2

    # Fill gaps along interior horizontal bars containing at least three original marks.
    for r in range(r0 + 1, r1):
        cols = [c for c in range(c0, c1 + 1) if grid[r][c] != bg]
        if len(cols) >= 3:
            for c in range(min(cols), max(cols) + 1):
                if out[r][c] == bg:
                    out[r][c] = 2

