def transform(grid):
    """Overlay matching binary panels separated by a solid line.

    The only palette color shared by the panels is their background. Mark
    cells with 3 where both panels have that background; elsewhere retain it.
    """
    h, w = len(grid), len(grid[0])
    candidates = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and r == h - r - 1:
            candidates.append((0, r))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and c == w - c - 1:
            candidates.append((1, c))
    for axis, sep in candidates:
        if axis == 0:
            a, b = grid[:sep], grid[sep + 1:]
        else:
            a = [row[:sep] for row in grid]
            b = [row[sep + 1:] for row in grid]
        if not a or len(a) != len(b) or any(len(x) != len(y) for x, y in zip(a, b)):
            continue
        shared = ({v for row in a for v in row} &
                  {v for row in b for v in row})
        if len(shared) != 1:
            continue
        bg = next(iter(shared))
        return [[3 if x == bg and y == bg else bg for x, y in zip(ra, rb)]
                for ra, rb in zip(a, b)]
    raise ValueError('No matching equal-sized panels with a solid separator')
